const htmlPlugin = require('prettier/parser-html');

const code = angularTemplate;

const formatted = format(code, {
  parser: 'angular',          // Use the Angular HTML parser
  plugins: [htmlPlugin],      // Load the built-in HTML parser
  // You can add any other Prettier options here,
  // for example, printWidth, tabWidth, etc.
});

console.log(formatted);

